const inScopeParts = parts.filter((part) => inScope.has(partKey(part)))
  if (inScopeParts.length === 0) {
    return NA
  }

if (requiredSatisfied) {
    return FULFILLED
  }
  return started ? IN_PROGRESS : NOT_STARTED

